type Result<T> =
  | { ok: true; value: T }
  | { ok: false; error: string };

function unwrap<T>(result: Result<T>): T {
  if (result.ok) return result.value; // narrowed to success
  throw new Error(result.error);       // narrowed to failure
}

console.log(unwrap({ ok: true, value: 42 }));
try { unwrap({ ok: false, error: 'nope' }); } catch (e) { console.log(String(e)); }

