type State =
  | { status: 'loading' }
  | { status: 'success'; data: string }
  | { status: 'error'; error: string };

function assertNever(x: never): never { throw new Error(String(x)); }

function render(s: State): string {
  switch (s.status) {
    case 'loading': return 'Loading...';
    case 'success': return 'Data: ' + s.data;
    case 'error': return 'Error: ' + s.error;
    default: return assertNever(s);
  }
}

console.log(render({ status: 'success', data: 'x' }));
// render({ status: 'success', error: 'y' }); // compile error: error not on success

type Action =
  | { type: 'increment'; by: number }
  | { type: 'decrement'; by: number }
  | { type: 'reset' };

function assertNever(x: never): never {
  throw new Error('Unhandled action: ' + JSON.stringify(x));
}

function reducer(count: number, action: Action): number {
  switch (action.type) {
    case 'increment': return count + action.by;
    case 'decrement': return count - action.by;
    case 'reset': return 0;
    default: return assertNever(action);
  }
}

let state = 0;
state = reducer(state, { type: 'increment', by: 5 });
state = reducer(state, { type: 'decrement', by: 2 });
console.log(state);
console.log(reducer(state, { type: 'reset' }));
